+            SetMockTime(WITH_LOCK(node.chainman->GetMutex(),
+                                  return node.chainman->ActiveTip()->Time()) + mock_offset);
+            const bool min_difficulty_window{mock_offset > std::chrono::minutes{20}};
+            node::BlockWaitOptions wait_options;
